import{_ as r,C as n,o as c,c as o,j as s,a as t,E as m,a2 as p,w as h}from"./chunks/framework.B-bxTAy7.js";const b=JSON.parse('{"title":"功率因数 cosφ","description":"有功、无功、视在三种功率的物理意义，功率三角形的读法，以及提高功率因数为什么能省电。","frontmatter":{"title":"功率因数 cosφ","description":"有功、无功、视在三种功率的物理意义，功率三角形的读法，以及提高功率因数为什么能省电。"},"headers":[],"relativePath":"ee/prereq/power-factor.md","filePath":"ee/prereq/power-factor.md","lastUpdated":1792416913000}'),g={name:"ee/prereq/power-factor.md"};function d(x,a,y,w,u,k){const e=n("Meta"),l=n("FigBox"),i=n("CircuitFig");return c(),o("div",null,[a[1]||(a[1]=s("h1",{id:"功率因数-cosφ",tabindex:"-1"},[t("功率因数 cosφ "),s("a",{class:"header-anchor",href:"#功率因数-cosφ","aria-label":'Permalink to "功率因数 cosφ"'},"​")],-1)),m(e,{time:"5 min",level:"卡片",note:"cosφ 是「容量利用率」：同样的变压器容量，cosφ 低就得多拉电流"}),a[2]||(a[2]=p('<p>一句话结论：<strong>功率因数 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>cos</mi><mo>⁡</mo><mi>φ</mi><mo>=</mo><mi>P</mi><mi mathvariant="normal">/</mi><mi>S</mi></mrow><annotation encoding="application/x-tex">\\cos\\varphi = P/S</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mop">cos</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">φ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mord">/</span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span></span></span></span> 是设备容量的利用率——同样一台变压器，<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>cos</mi><mo>⁡</mo><mi>φ</mi></mrow><annotation encoding="application/x-tex">\\cos\\varphi</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mop">cos</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">φ</span></span></span></span> 越低，能送出的有功功率越少、线路电流越大。</strong></p><h2 id="日常说法与正式定义" tabindex="-1">日常说法与正式定义 <a class="header-anchor" href="#日常说法与正式定义" aria-label="Permalink to &quot;日常说法与正式定义&quot;">​</a></h2><ul><li>日常说法：你雇了一辆卡车（容量），它拉了半车货（有用功），剩下的半车位置是空的，但车照样得付钱、照样在费油。空着的比例就是功率因数。</li><li>正式定义：交流电路中电压与电流的相位差 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>φ</mi></mrow><annotation encoding="application/x-tex">\\varphi</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">φ</span></span></span></span> 决定了三种功率的分配：</li></ul><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>P</mi><mo>=</mo><mi>U</mi><mi>I</mi><mi>cos</mi><mo>⁡</mo><mi>φ</mi><mspace width="1em"></mspace><mo stretchy="false">[</mo><mtext>W</mtext><mo stretchy="false">]</mo><mspace width="2em"></mspace><mi>Q</mi><mo>=</mo><mi>U</mi><mi>I</mi><mi>sin</mi><mo>⁡</mo><mi>φ</mi><mspace width="1em"></mspace><mo stretchy="false">[</mo><mtext>var</mtext><mo stretchy="false">]</mo><mspace width="2em"></mspace><mi>S</mi><mo>=</mo><mi>U</mi><mi>I</mi><mspace width="1em"></mspace><mo stretchy="false">[</mo><mtext>VA</mtext><mo stretchy="false">]</mo></mrow><annotation encoding="application/x-tex">P = UI\\cos\\varphi \\quad[\\text{W}] \\qquad Q = UI\\sin\\varphi \\quad[\\text{var}] \\qquad S = UI \\quad[\\text{VA}] </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">U</span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">cos</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">φ</span><span class="mspace" style="margin-right:1em;"></span><span class="mopen">[</span><span class="mord text"><span class="mord">W</span></span><span class="mclose">]</span><span class="mspace" style="margin-right:2em;"></span><span class="mord mathnormal">Q</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">U</span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">sin</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">φ</span><span class="mspace" style="margin-right:1em;"></span><span class="mopen">[</span><span class="mord text"><span class="mord">var</span></span><span class="mclose">]</span><span class="mspace" style="margin-right:2em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">U</span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mspace" style="margin-right:1em;"></span><span class="mopen">[</span><span class="mord text"><span class="mord">VA</span></span><span class="mclose">]</span></span></span></span></span><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msup><mi>S</mi><mn>2</mn></msup><mo>=</mo><msup><mi>P</mi><mn>2</mn></msup><mo>+</mo><msup><mi>Q</mi><mn>2</mn></msup><mspace width="2em"></mspace><mi>cos</mi><mo>⁡</mo><mi>φ</mi><mo>=</mo><mfrac><mi>P</mi><mi>S</mi></mfrac></mrow><annotation encoding="application/x-tex">S^2 = P^2 + Q^2 \\qquad \\cos\\varphi = \\frac{P}{S} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8641em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.9474em;vertical-align:-0.0833em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0585em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal">Q</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">cos</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">φ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.0463em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span><h2 id="三种功率的物理意义" tabindex="-1">三种功率的物理意义 <a class="header-anchor" href="#三种功率的物理意义" aria-label="Permalink to &quot;三种功率的物理意义&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功率</th><th>符号</th><th>含义</th><th>谁在用</th></tr></thead><tbody><tr><td>有功功率</td><td><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>P</mi></mrow><annotation encoding="application/x-tex">P</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span></span></span></span></td><td>真正被消耗掉的（做功、发热）</td><td>用户的活</td></tr><tr><td>无功功率</td><td><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi></mrow><annotation encoding="application/x-tex">Q</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span></td><td>在电源与储能元件之间来回交换的（建立磁场/电场必需）</td><td>电感、电容</td></tr><tr><td>视在功率</td><td><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>S</mi></mrow><annotation encoding="application/x-tex">S</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span></span></span></span></td><td>电源需要提供的容量</td><td>变压器铭牌</td></tr></tbody></table>',7)),m(l,{title:"功率三角形：斜边是容量，直角边是干活的比例",kind:"结构",note:"S 固定不动（电源就那么大容量）时，阻抗角越大，Q 越长、P 越短。cosφ = P/S 就是容量利用率。"},{default:h(()=>[...a[0]||(a[0]=[s("svg",{viewBox:"0 0 470 250",class:"sf",xmlns:"http://www.w3.org/2000/svg",fill:"none",stroke:"var(--vp-c-text-1)","stroke-width":"1.6","stroke-linecap":"round","stroke-linejoin":"round",role:"img"},[s("defs",null,[s("marker",{id:"pf-a",viewBox:"0 0 10 10",refX:"8",refY:"5",markerWidth:"7",markerHeight:"7",orient:"auto"},[s("path",{d:"M 0 0 L 10 5 L 0 10 z",fill:"var(--vp-c-text-1)"})])]),s("g",{"font-size":"12.5",fill:"var(--vp-c-text-1)",class:"sf-t"},[s("line",{x1:"60",y1:"200",x2:"360",y2:"200"}),s("line",{x1:"300",y1:"200",x2:"300",y2:"60"}),s("line",{x1:"60",y1:"200",x2:"300",y2:"60","stroke-width":"2.2","marker-end":"url(#pf-a)"}),s("text",{x:"170",y:"222","text-anchor":"middle"},"P（有功）"),s("text",{x:"312",y:"135"},"Q（无功）"),s("text",{x:"196",y:"118"},"S（视在）"),s("path",{d:"M 108 200 A 48 48 0 0 0 100 171",fill:"none",stroke:"var(--vp-c-text-3)","stroke-width":"1.3"}),s("text",{x:"118",y:"184",fill:"var(--vp-c-text-3)","font-size":"12"},"φ"),s("text",{x:"60",y:"242","text-anchor":"middle",fill:"var(--vp-c-text-3)","font-size":"11.5"},"cosφ = P / S —— 斜边越长，能干活的比例越低"),s("text",{x:"60",y:"34",fill:"var(--vp-c-text-3)","font-size":"11.5"},"容量 S 固定时，负载越感性，Q 越长、P 越短")])],-1)])]),_:1}),a[3]||(a[3]=p('<h2 id="为什么必须提高" tabindex="-1">为什么必须提高 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>cos</mi><mo>⁡</mo><mi>φ</mi></mrow><annotation encoding="application/x-tex">\\cos\\varphi</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mop">cos</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">φ</span></span></span></span> <a class="header-anchor" href="#为什么必须提高" aria-label="Permalink to &quot;为什么必须提高 $\\cos\\varphi$&quot;">​</a></h2><p><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>P</mi></mrow><annotation encoding="application/x-tex">P</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span></span></span></span> 一定时，<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>I</mi><mo>=</mo><mi>P</mi><mi mathvariant="normal">/</mi><mo stretchy="false">(</mo><mi>U</mi><mi>cos</mi><mo>⁡</mo><mi>φ</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">I = P/(U\\cos\\varphi)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mord">/</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.109em;">U</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">cos</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">φ</span><span class="mclose">)</span></span></span></span>。所以 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>cos</mi><mo>⁡</mo><mi>φ</mi></mrow><annotation encoding="application/x-tex">\\cos\\varphi</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mop">cos</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">φ</span></span></span></span> 越低：</p><ul><li>电流 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>I</mi></mrow><annotation encoding="application/x-tex">I</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span></span></span></span> 越大 → 线路损耗 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>I</mi><mn>2</mn></msup><mi>R</mi></mrow><annotation encoding="application/x-tex">I^2R</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span></span></span></span> 越大、压降越大；</li><li>视在功率 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>S</mi></mrow><annotation encoding="application/x-tex">S</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span></span></span></span> 越大 → 变压器、导线、开关的容量被白白占掉。</li></ul><h2 id="常见误解" tabindex="-1">常见误解 <a class="header-anchor" href="#常见误解" aria-label="Permalink to &quot;常见误解&quot;">​</a></h2><ol><li><strong>「无功功率是浪费的电」</strong> → 无功不做功，但它建立磁场与电场，是电感电容正常工作必需的。浪费的是<strong>容量和线路损耗</strong>，不是电能本身。</li><li><strong>「功率因数低了，负载就多耗电了」</strong> → 负载的 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>P</mi></mrow><annotation encoding="application/x-tex">P</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span></span></span></span> 没变，多出来的是电网侧的损耗。责任在电网，但账单会反映出来。</li><li><strong>「功率因数是电抗器的属性」</strong> → 电机、变压器、荧光灯镇流器都是感性负载，天生 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>cos</mi><mo>⁡</mo><mi>φ</mi></mrow><annotation encoding="application/x-tex">\\cos\\varphi</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mop">cos</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">φ</span></span></span></span> 低；电容并联进去可以把滞后角抵消掉。</li></ol><h2 id="例题" tabindex="-1">例题 <a class="header-anchor" href="#例题" aria-label="Permalink to &quot;例题&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">例 1 · 一台设备把功率因数从 0.8 提到 0.95 能省多少电流</p><p><strong>题目</strong>：某感性负载接在 220 V、50 Hz 电源上，功率因数 0.8，电流 10 A。求有功功率；若并联电容把功率因数提到 0.95，电流变成多少？</p><p><strong>先想什么</strong>：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>P</mi></mrow><annotation encoding="application/x-tex">P</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span></span></span></span> 由负载决定，加电容前后不变；变的只有电流和容量。所以先算出 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>P</mi></mrow><annotation encoding="application/x-tex">P</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span></span></span></span>，再反推新电流。<em>（先认出「什么量没变」，题目就解了一半。）</em></p><p><strong>步骤</strong>：</p><ol><li>有功功率：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>P</mi><mo>=</mo><mi>U</mi><mi>I</mi><mi>cos</mi><mo>⁡</mo><mi>φ</mi><mo>=</mo><mn>220</mn><mo>×</mo><mn>10</mn><mo>×</mo><mn>0.8</mn><mo>=</mo><mn>1760</mn><mtext> W</mtext></mrow><annotation encoding="application/x-tex">P = UI\\cos\\varphi = 220 \\times 10 \\times 0.8 = 1760\\ \\text{W}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">U</span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">cos</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">φ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">220</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">10</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.8</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">1760</span><span class="mspace"> </span><span class="mord text"><span class="mord">W</span></span></span></span></span>。<em>（为什么先求 P：它是负载真正消耗的功率，也是补偿前后的不变量。）</em></li><li>补偿后电流：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>I</mi><mo mathvariant="normal" lspace="0em" rspace="0em">′</mo></msup><mo>=</mo><mi>P</mi><mi mathvariant="normal">/</mi><mo stretchy="false">(</mo><mi>U</mi><mi>cos</mi><mo>⁡</mo><msup><mi>φ</mi><mo mathvariant="normal" lspace="0em" rspace="0em">′</mo></msup><mo stretchy="false">)</mo><mo>=</mo><mn>1760</mn><mi mathvariant="normal">/</mi><mo stretchy="false">(</mo><mn>220</mn><mo>×</mo><mn>0.95</mn><mo stretchy="false">)</mo><mo>=</mo><mn>8.42</mn><mtext> A</mtext></mrow><annotation encoding="application/x-tex">I&#39; = P/(U\\cos\\varphi&#39;) = 1760/(220 \\times 0.95) = 8.42\\ \\text{A}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7519em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0019em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mord">/</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.109em;">U</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">cos</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">φ</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1760/</span><span class="mopen">(</span><span class="mord">220</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">0.95</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">8.42</span><span class="mspace"> </span><span class="mord text"><span class="mord">A</span></span></span></span></span>。</li><li>线路电流下降 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>10</mn><mo>−</mo><mn>8.42</mn><mo>=</mo><mn>1.58</mn><mtext> A</mtext></mrow><annotation encoding="application/x-tex">10 - 8.42 = 1.58\\ \\text{A}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">10</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">8.42</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">1.58</span><span class="mspace"> </span><span class="mord text"><span class="mord">A</span></span></span></span></span>，约减少 16%。</li></ol><p><strong>验算</strong>：补偿后 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>S</mi><mo mathvariant="normal" lspace="0em" rspace="0em">′</mo></msup><mo>=</mo><mn>220</mn><mo>×</mo><mn>8.42</mn><mo>=</mo><mn>1853</mn><mtext> VA</mtext></mrow><annotation encoding="application/x-tex">S&#39; = 220 \\times 8.42 = 1853\\ \\text{VA}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7519em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">220</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">8.42</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">1853</span><span class="mspace"> </span><span class="mord text"><span class="mord">VA</span></span></span></span></span>，小于原来的 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>2200</mn><mtext> VA</mtext></mrow><annotation encoding="application/x-tex">2200\\ \\text{VA}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">2200</span><span class="mspace"> </span><span class="mord text"><span class="mord">VA</span></span></span></span></span> ✓（容量被释放出来了）。再验算功率：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1760</mn><mo>=</mo><mn>220</mn><mo>×</mo><mn>8.42</mn><mo>×</mo><mn>0.95</mn><mo>=</mo><mn>1759.6</mn><mtext> W</mtext></mrow><annotation encoding="application/x-tex">1760 = 220 \\times 8.42 \\times 0.95 = 1759.6\\ \\text{W}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1760</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">220</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">8.42</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.95</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">1759.6</span><span class="mspace"> </span><span class="mord text"><span class="mord">W</span></span></span></span></span>，与补偿前一致 ✓。</p></div>',7)),m(i,{kind:"pf-comp",title:"并联电容做功率因数补偿",note:"电容并联在负载两端，只改变线路电流，不改变负载两端的电压、电流和功率——它只在电源与负载之间抵消掉那部分无功电流。"}),a[4]||(a[4]=s("h2",{id:"在正文里什么时候用得上",tabindex:"-1"},[t("在正文里什么时候用得上 "),s("a",{class:"header-anchor",href:"#在正文里什么时候用得上","aria-label":'Permalink to "在正文里什么时候用得上"'},"​")],-1)),a[5]||(a[5]=s("blockquote",null,[s("p",null,[t("完整内容见 "),s("a",{href:"./../04-ac/power"},"10 · 功率与功率因数")])],-1)),a[6]||(a[6]=s("p",null,"选变压器容量、算线路损耗、算电费（工业用电按功率因数奖惩）、判断一台设备为什么「电流超标但不跳闸」，都要先回到这张卡的功率三角形。",-1))])}const M=r(g,[["render",d]]);export{b as __pageData,M as default};
